import re
from decimal import Decimal

# Largest accepted amount, 1000000.00, expressed in cents.
MAX_CENTS = 100_000_000

# ASCII-only grammar for string amounts. Fullmatch is used, so no
# surrounding whitespace, exponents, underscores, or non-ASCII digits pass.
_STRING_AMOUNT = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def to_cents(value):
    """Validate an amount and return it as an exact integer number of cents.

    All arithmetic here is exact integer or exact Decimal construction. The
    caller's decimal context is never consulted, so low precision cannot
    round the value.
    """
    if isinstance(value, bool):
        raise ValueError("boolean is not a valid amount")

    if isinstance(value, int):
        if value <= 0:
            raise ValueError("amount must be positive")
        if value > MAX_CENTS // 100:
            raise ValueError("amount exceeds 1000000.00")
        return value * 100

    if isinstance(value, str):
        if _STRING_AMOUNT.fullmatch(value) is None:
            raise ValueError(f"invalid amount string: {value!r}")
        value = Decimal(value)  # exact; the string grammar was checked above
    elif not isinstance(value, Decimal):
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not value.is_finite():
        raise ValueError("amount must be finite")

    sign, digits, exponent = value.as_tuple()
    significant = "".join(map(str, digits)).rstrip("0")
    if not significant:
        raise ValueError("amount must be nonzero")
    if sign:
        raise ValueError("amount must be positive")

    # Normalize: value == int(significant) * 10**exponent with no trailing zeros.
    exponent += len("".join(map(str, digits))) - len(significant)
    # Bound the magnitude before doing any large powers of ten.
    if len(significant) + exponent > 7:
        raise ValueError("amount exceeds 1000000.00")
    if exponent < -2:
        raise ValueError("amount is not exactly representable in cents")

    cents = int(significant) * 10 ** (exponent + 2)
    if cents > MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def cents_to_amount(cents):
    """Return an exact Decimal with exponent -2 for a positive cent count."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_amount(to_cents(value))


def format_amount(value):
    return format(value, ".2f")
