import os, sys
sys.path.insert(0, os.getcwd())
from decimal import Decimal, getcontext, localcontext
from src.money import parse_amount, format_amount
from src.api import make_invoice


def raises(fn, arg):
    try:
        fn(arg)
    except ValueError:
        return True
    return False


def check_strings_ok():
    cases = {
        "12.50": "12.50", "12": "12.00", "+3.1": "3.10", "-0": None,
        "007.50": "7.50", "0.5": "0.50", "1000000.00": "1000000.00",
        "1000000": "1000000.00", "0.10000": "0.10", "0.01": "0.01",
    }
    for s, want in cases.items():
        if want is None:
            assert raises(parse_amount, s), s
            continue
        got = parse_amount(s)
        assert isinstance(got, Decimal) and got.as_tuple().exponent == -2, s
        assert format_amount(got) == want, (s, got)


def check_strings_bad():
    bad = [".1", "1.", "", " 1", "1 ", "1\n", "1e2", "1E2", "1_000", "١٢",
           "\uff11.00", "+", "-", "1.2.3", "--1", "0x10", "inf", "nan",
           "0.001", "-1.00", "0.00", "1000000.01", "1000001", "1,00"]
    for s in bad:
        assert raises(parse_amount, s), repr(s)


def check_types():
    for v in [1.0, 0.5, True, False, None, b"1.00", [1], 1 + 0j]:
        assert raises(parse_amount, v), repr(v)
    for v in [0, -1, 1000001]:
        assert raises(parse_amount, v), v
    assert format_amount(parse_amount(5)) == "5.00"
    assert format_amount(parse_amount(1000000)) == "1000000.00"


def check_decimals():
    assert format_amount(parse_amount(Decimal("1.5E+1"))) == "15.00"
    assert format_amount(parse_amount(Decimal("1E-2"))) == "0.01"
    assert format_amount(parse_amount(Decimal("1.20000E-1"))) == "0.12"
    assert format_amount(parse_amount(Decimal("100.000000000000000000000"))) == "100.00"
    bad = [Decimal("NaN"), Decimal("sNaN"), Decimal("Infinity"), Decimal("-Infinity"),
           Decimal("0"), Decimal("-0.00"), Decimal("-1"), Decimal("1000000.01"),
           Decimal("1E+7"), Decimal("1E+1000000000"), Decimal("1E-1000000000"),
           Decimal("0.001"), Decimal("1.005"), Decimal("0.0000000000000000000001"),
           Decimal("1.2500000000000000000000000000000001")]
    for v in bad:
        assert raises(parse_amount, v), v


def check_nonzero_fraction_not_rounded():
    # Nonzero sub-cent digits must reject, never round.
    assert raises(parse_amount, "0.005")
    assert raises(parse_amount, Decimal("12.345"))


def check_precision_independent():
    with localcontext() as c:
        c.prec = 3
        before = (getcontext().prec, getcontext().rounding)
        assert format_amount(parse_amount("1234567.89"[:-3] + ".00")) == "1234567.00"
        assert format_amount(parse_amount(Decimal("999999.99"))) == "999999.99"
        assert format_amount(parse_amount("123.45")) == "123.45"
        assert format_amount(make_invoice(["999999.99", "0.01"])["total"] and parse_amount("1.00")) == "1.00"
        assert make_invoice(["999999.99", "0.01"]) == {"total": "1000000.00", "count": 2}
        assert make_invoice(["123.45", "0.55", "1.00"]) == {"total": "125.00", "count": 3}
        assert make_invoice(["0.10", "0.20"]) == {"total": "0.30", "count": 2}
        assert (getcontext().prec, getcontext().rounding) == before
        assert getcontext().prec == 3 or True
    assert getcontext().prec == 28 or getcontext().prec == 28


def check_make_invoice():
    assert make_invoice([]) == {"total": "0.00", "count": 0}
    assert make_invoice(["1.20", "2.30"]) == {"total": "3.50", "count": 2}
    assert make_invoice([Decimal("1E+2"), 5, "0.01"]) == {"total": "105.01", "count": 3}
    assert make_invoice(["1000000.00"]) == {"total": "1000000.00", "count": 1}
    for v in ["1.20", (("1.20"),), None, "1.20", {"a": 1}]:
        if not isinstance(v, list):
            assert raises(make_invoice, v), repr(v)
    assert raises(make_invoice, ("1.20",))
    assert raises(make_invoice, "1.20")
    assert raises(make_invoice, None)
    assert raises(make_invoice, ["1.00", "0.00"])
    assert raises(make_invoice, ["1.00", 1.5])
    assert raises(make_invoice, ["1.00", "1."])
    assert raises(make_invoice, ["1000000.00", "0.01"])
    assert raises(make_invoice, ["500000.00", "500000.01"])


def check_no_input_mutation():
    items = ["1.00", Decimal("2.5"), 3]
    snapshot = list(items)
    make_invoice(items)
    assert items == snapshot and all(type(a) is type(b) for a, b in zip(items, snapshot))


if __name__ == "__main__":
    for name, fn in list(globals().items()):
        if name.startswith("check_") and callable(fn):
            fn()
    print("amount checks passed")
